    } catch (error) {
      clearTimeout(timeoutId);

      if (error instanceof Error) {
        if (error.name === 'AbortError') {
          throw new Error('Request timeout - flat-lay generation took too long');
        }
        throw error;
      }

      throw new Error('Unknown error during flat-lay generation');
    }
  }

  /**
